def lum(hex):
    hex=hex.lstrip('#')
    r,g,b=[int(hex[i:i+2],16)/255 for i in (0,2,4)]
    def f(c): return c/12.92 if c<=0.03928 else ((c+0.055)/1.055)**2.4
    return 0.2126*f(r)+0.7152*f(g)+0.0722*f(b)
def ratio(a,b):
    la,lb=lum(a),lum(b)
    return (max(la,lb)+0.05)/(min(la,lb)+0.05)
pairs=[("#667085","#ffffff"),("#667085","#f6f7f9"),("#667085","#eef1f5"),("#98a6ba","#151c28"),("#98a6ba","#0f141d"),("#2457d6","#ffffff"),("#ffffff","#2457d6"),("#7aa2ff","#0b1020"),("#0b1020","#7aa2ff"),("#157347","#ffffff"),("#b42318","#ffffff"),("#9a6700","#ffffff"),("#e0b54a","#0f141d"),("#ff8f86","#0f141d"),("#8fb0ff","#0f141d")]
for a,b in pairs:
    print(a,b,round(ratio(a,b),2))
